//! Register map: byte offsets on BAR0, reset values, field shifts and masks.
//!
//! Everything here is generated by bindgen from `host/include/fw16_fpga_regs.h`
//! (itself generated from `gateware/regmap/map_v0.ml`).

#![allow(non_upper_case_globals, dead_code)]

include!(concat!(env!("OUT_DIR"), "/fw16_fpga_regs.rs"));

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn constants_match_the_map() {
        assert_eq!(FW16_FPGA_ID, 0x0000);
        assert_eq!(FW16_FPGA_ID_RESET, 0x4F4D_4E49);
        assert_eq!(FW16_FPGA_SCRATCH, 0x0008);
        assert_eq!(FW16_FPGA_SRC_CTL, 0x1000);
        assert_eq!(FW16_FPGA_SRC_RATE_RESET, 0x1_0000);
        assert_eq!(FW16_FPGA_SNK_BEATS_HI, 0x200C);
        assert_eq!(FW16_FPGA_RING_CLEAR, 0x300C);
        assert_eq!(FW16_FPGA_VERSION_MAJOR_MASK, 0xFFFF_0000);
        assert_eq!(FW16_FPGA_STATUS_RING_OVERFLOW_SHIFT, 3);
    }

    #[test]
    fn constants_are_u32() {
        // bindgen picks the type from the literal; offsets must stay u32 so
        // `Transport::read32(FW16_FPGA_*)` needs no casts.
        let _: u32 = FW16_FPGA_SRC_BEATS_LO;
        let _: u32 = FW16_FPGA_SNK_CTL_MODE_MASK;
    }
}
